import React, { useEffect, useRef, useState, type ComponentType, type ReactNode } from 'react';
import {
  Animated,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from 'react-native';

import { PlayerIcon, type PlayerIconName } from './PlayerIcon';
import {
  canStepSpeed,
  captionLine,
  captionSwitchTarget,
  MENU_LINE_HEIGHT,
  MENU_PADDING,
  ROTATION_CHOICES,
  speedLabel,
  stepSpeed,
  type CaptionChoice,
  type MenuLine,
  type RotationLock,
} from './playerLogic';

/**
 * The options menu: a small box that drops down from the options button. One line per setting,
 * its name on the left and its control on the right, nothing else.
 *
 * It is a layer inside the player, never a window of its own, so it turns with the player and
 * behaves the same on iPhone, Android and the web.
 */

/** Frosted glass for the menu, supplied by the app (a blur view on iPhone). Without one the menu is a dark panel. */
export type PlayerGlass = ComponentType<{ style?: StyleProp<ViewStyle>; children?: ReactNode }>;

export type PlayerMenuProps = {
  lines: readonly MenuLine[];
  width: number;
  maxHeight: number;
  speed: number;
  onSpeed: (rate: number) => void;
  loop: boolean;
  onLoop: (loop: boolean) => void;
  rotation: RotationLock;
  onRotation: (rotation: RotationLock) => void;
  captions: readonly CaptionChoice[];
  /** The caption track last shown for this file; -1 when there has been none. */
  captionMemory: number;
  onCaption: (index: number) => void;
  accent: string;
  glass?: PlayerGlass;
};

// Animations run on the device's own thread where there is one; a browser has none.
const NATIVE = Platform.OS !== 'web';

const TURN_ICON: Record<RotationLock, PlayerIconName> = {
  auto: 'turn-auto',
  portrait: 'turn-portrait',
  landscape: 'turn-landscape',
};

export function PlayerMenu(props: PlayerMenuProps) {
  const { lines, captions, captionMemory, accent, glass } = props;
  const [languagesOpen, setLanguagesOpen] = useState(false);
  const line = captionLine(captions, captionMemory);
  const Box: PlayerGlass = glass ?? View;

  return (
    <Box
      style={[
        styles.menu,
        glass ? styles.menuOverGlass : styles.menuSolid,
        Platform.OS === 'web' ? WEB_GLASS : null,
        { width: props.width, maxHeight: props.maxHeight },
      ]}
    >
      <ScrollView bounces={false} showsVerticalScrollIndicator={false} contentContainerStyle={styles.body}>
        {lines.includes('speed') && (
          <Line icon="speed" name="Speed">
            <RoundButton
              icon="minus"
              label="Slower"
              disabled={!canStepSpeed(props.speed, -1)}
              onPress={() => props.onSpeed(stepSpeed(props.speed, -1))}
            />
            <Text style={styles.speedValue} maxFontSizeMultiplier={1.15} accessibilityLabel={`Speed ${speedLabel(props.speed)}`}>
              {speedLabel(props.speed)}
            </Text>
            <RoundButton
              icon="plus"
              label="Faster"
              disabled={!canStepSpeed(props.speed, 1)}
              onPress={() => props.onSpeed(stepSpeed(props.speed, 1))}
            />
          </Line>
        )}

        {lines.includes('loop') && (
          <Line icon="loop" name="Loop">
            <Toggle label="Loop" value={props.loop} onChange={props.onLoop} accent={accent} />
          </Line>
        )}

        {lines.includes('orientation') && (
          <Line icon="turn-auto" name="Orientation">
            <View style={styles.turnRow}>
              {ROTATION_CHOICES.map((choice) => {
                const selected = choice.value === props.rotation;
                return (
                  <Pressable
                    key={choice.value}
                    style={[styles.turnButton, selected && styles.turnButtonOn]}
                    onPress={() => props.onRotation(choice.value)}
                    accessibilityRole="button"
                    accessibilityLabel={`Orientation ${choice.label}`}
                    accessibilityState={{ selected }}
                    hitSlop={4}
                  >
                    <PlayerIcon name={TURN_ICON[choice.value]} size={19} color={selected ? '#111' : '#fff'} />
                  </Pressable>
                );
              })}
            </View>
          </Line>
        )}

        {lines.includes('captions') && (
          <Line icon="captions" name="Captions" dim={!line.available}>
            <Pressable
              style={[styles.language, !line.available && styles.spent, languagesOpen && styles.languageOpen]}
              onPress={() => setLanguagesOpen((open) => !open)}
              disabled={line.tracks.length < 2}
              accessibilityRole="button"
              accessibilityLabel={line.shown ? `Caption language ${line.shown.label}` : 'No captions in this video'}
              accessibilityState={{ expanded: languagesOpen, disabled: line.tracks.length < 2 }}
              hitSlop={6}
            >
              <Text style={styles.languageText} numberOfLines={1} maxFontSizeMultiplier={1.15}>
                {line.shown ? line.shown.short : 'None'}
              </Text>
              {line.tracks.length > 1 && <PlayerIcon name="caret-down" size={10} color="#fff" />}
            </Pressable>
            <Toggle
              label="Captions"
              value={line.on}
              disabled={!line.available}
              onChange={(on) => props.onCaption(captionSwitchTarget(captions, on, captionMemory))}
              accent={accent}
            />
          </Line>
        )}

        {languagesOpen && line.tracks.length > 1 && (
          <View style={styles.languages}>
            {line.tracks.map((track) => {
              const chosen = track.index === line.shown?.index;
              return (
                <Pressable
                  key={track.key}
                  style={styles.languageLine}
                  onPress={() => {
                    props.onCaption(track.index);
                    setLanguagesOpen(false);
                  }}
                  accessibilityRole="button"
                  accessibilityLabel={`Captions ${track.label}`}
                  accessibilityState={{ selected: chosen }}
                >
                  <View style={styles.languageTick}>
                    {chosen && <PlayerIcon name="check" size={14} color="#fff" />}
                  </View>
                  <Text style={[styles.languageName, chosen && styles.languageNameOn]} numberOfLines={1}>
                    {track.label}
                  </Text>
                  <Text style={styles.languageCode}>{track.short}</Text>
                </Pressable>
              );
            })}
          </View>
        )}
      </ScrollView>
    </Box>
  );
}

function Line(props: { icon: PlayerIconName; name: string; dim?: boolean; children: ReactNode }) {
  return (
    <View style={styles.line}>
      <View style={props.dim ? styles.spent : undefined}>
        <PlayerIcon name={props.icon} size={18} />
      </View>
      <Text style={[styles.lineName, props.dim && styles.spent]} numberOfLines={1} maxFontSizeMultiplier={1.15}>
        {props.name}
      </Text>
      {props.children}
    </View>
  );
}

function RoundButton(props: { icon: PlayerIconName; label: string; disabled?: boolean; onPress: () => void }) {
  return (
    <Pressable
      style={[styles.round, props.disabled && styles.spent]}
      onPress={props.onPress}
      disabled={props.disabled}
      accessibilityRole="button"
      accessibilityLabel={props.label}
      accessibilityState={{ disabled: !!props.disabled }}
      hitSlop={6}
    >
      <PlayerIcon name={props.icon} size={14} />
    </Pressable>
  );
}

/** The player's own switch, so it is the same size and shape on every device. */
function Toggle(props: {
  label: string;
  value: boolean;
  onChange: (value: boolean) => void;
  accent: string;
  disabled?: boolean;
}) {
  const { value } = props;
  const slide = useRef(new Animated.Value(value ? 1 : 0)).current;
  useEffect(() => {
    Animated.timing(slide, { toValue: value ? 1 : 0, duration: 140, useNativeDriver: NATIVE }).start();
  }, [slide, value]);
  return (
    <Pressable
      style={[styles.toggle, { backgroundColor: value ? props.accent : 'rgba(255,255,255,0.24)' }, props.disabled && styles.spent]}
      onPress={() => props.onChange(!value)}
      disabled={props.disabled}
      accessibilityRole="switch"
      accessibilityLabel={props.label}
      accessibilityState={{ checked: value, disabled: !!props.disabled }}
      hitSlop={8}
    >
      <Animated.View
        style={[
          styles.toggleKnob,
          { transform: [{ translateX: slide.interpolate({ inputRange: [0, 1], outputRange: [0, 16] }) }] },
        ]}
      />
    </Pressable>
  );
}

// A browser blurs what is behind the menu by itself; the style name is not one React Native knows.
const WEB_GLASS = {
  backdropFilter: 'blur(18px)',
  WebkitBackdropFilter: 'blur(18px)',
  backgroundColor: 'rgba(28,28,30,0.72)',
} as unknown as ViewStyle;

const styles = StyleSheet.create({
  menu: {
    borderRadius: 16,
    overflow: 'hidden',
    borderWidth: StyleSheet.hairlineWidth * 2,
    borderColor: 'rgba(255,255,255,0.18)',
  },
  // Over real glass the panel only tints it; without glass it carries its own darkness.
  menuOverGlass: { backgroundColor: 'rgba(28,28,30,0.42)' },
  menuSolid: { backgroundColor: 'rgba(28,28,30,0.94)' },
  body: { paddingVertical: MENU_PADDING },

  line: {
    height: MENU_LINE_HEIGHT,
    paddingHorizontal: 11,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 7,
  },
  lineName: { flex: 1, color: '#fff', fontSize: 14, fontWeight: '600' },
  spent: { opacity: 0.38 },

  round: {
    width: 28,
    height: 28,
    borderRadius: 14,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(255,255,255,0.16)',
  },
  speedValue: {
    width: 44,
    textAlign: 'center',
    color: '#fff',
    fontSize: 14,
    fontWeight: '700',
    fontVariant: ['tabular-nums'],
  },

  toggle: { width: 40, height: 24, borderRadius: 12, padding: 2, justifyContent: 'center' },
  toggleKnob: { width: 20, height: 20, borderRadius: 10, backgroundColor: '#fff' },

  turnRow: { flexDirection: 'row', gap: 4 },
  turnButton: {
    width: 30,
    height: 28,
    borderRadius: 9,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'rgba(255,255,255,0.16)',
  },
  turnButtonOn: { backgroundColor: '#fff' },

  language: {
    height: 28,
    minWidth: 38,
    maxWidth: 96,
    paddingHorizontal: 9,
    borderRadius: 9,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 5,
    backgroundColor: 'rgba(255,255,255,0.16)',
  },
  languageOpen: { backgroundColor: 'rgba(255,255,255,0.30)' },
  languageText: { color: '#fff', fontSize: 13, fontWeight: '700' },

  languages: {
    marginTop: 2,
    marginHorizontal: 8,
    marginBottom: 2,
    paddingVertical: 2,
    borderRadius: 11,
    backgroundColor: 'rgba(255,255,255,0.10)',
  },
  languageLine: { height: 36, paddingHorizontal: 8, flexDirection: 'row', alignItems: 'center', gap: 6 },
  languageTick: { width: 16, alignItems: 'center' },
  languageName: { flex: 1, color: 'rgba(255,255,255,0.86)', fontSize: 14, fontWeight: '500' },
  languageNameOn: { color: '#fff', fontWeight: '700' },
  languageCode: { color: 'rgba(255,255,255,0.5)', fontSize: 11, fontWeight: '700' },
});
